     Korea Open CourseWare - KOCW 




	    @font-face{
		    font-family:Pretendard;
			src:url(http://www.kocw.net/home/mobile/style/font/Pretendard-Regular.eot);
		    src:local('※'), url(http://www.kocw.net/home/mobile/style/font/Pretendard-Regular.woff) format('woff');
		}

		@font-face{
		    font-family:PretendardM;
			src:url(http://www.kocw.net/home/style/font/Pretendard-Medium.eot);
		    src:local('※'), url(http://www.kocw.net/home/style/font/Pretendard-Medium.woff) format('woff');
		}


	     body.web {
	         color: #4a4a4a;
	         width: 100%;
	         *height: 100%;
	         font-size: 12px;
	         line-height: 1em;
	         font-family: dotum, "돋움", sans-serif;
	         padding: 0px;
	         margin: 0px;
	     }

	     body.mobile {
	        line-height: 1;
	        font-family:Pretendard, Roboto, NotoSans, sans-serif; 
	        letter-spacing: -0.02em;
	     }

	     html,body,div,span,applet,object,iframe,h1,h2,h3,h4,h5,h6,p,blockquote,pre,a,abbr,acronym,address,big,cite,code,del,dfn,em,img,ins,kbd,q,s,samp,
		 small,strike,strong,sub,sup,tt,var,b,u,i,center,dl,dt,dd,ol,ul,li,fieldset,form,label,legend,table,caption,tbody,tfoot,thead,tr,th,td,article,
		 aside,canvas,details,embed,figure,figcaption,footer,header,hgroup,menu,
		 nav,output,ruby,section,summary,time,mark,audio,video {
			  margin: 0;
			  padding: 0;
			  border: 0;
			  font-size: 100%;
			  font: inherit;
			  vertical-align: baseline;
		}

		a {
  			  color: inherit;
  			  text-decoration: none;
		}

	    div, p, ol, ul, li, img, a, h1, h2, h3, h4, h5, h6, form, span, iframe, dl, dt, dd {
	         margin: 0px;
	         padding: 0px;
	     }
	     ul, ol { list-style: none}

	     div.notFoundPop{width:902px; height:214px; position:absolute; top:50%; left:50%; margin-left:-451px; margin-top:-127px;}
	     div.notFoundPop dt{}
	     div.notFoundPop dd.type01{color:#4D4D4D; margin-top:25px;}
	     div.notFoundPop dd.type01 ul{margin-top:14px;}
	     div.notFoundPop dd.type01 ul li{padding-left:9px; background:url(http://www.kocw.net/home/images/common/bg_found_li.gif) 2px 6px no-repeat; font-size:11px; color:#454545; line-height:150%;}
	     div.notFoundPop dd.type02 ul{margin-top:32px;}
	     div.notFoundPop dd.type02 ul li{float:left; margin-right:5px; display:inline;}


	     .errorW{max-width: 580px; width: 100%; margin: 0 auto; padding: 50px 25px; box-sizing: border-box; letter-spacing: -0.025em;}
		 .errorW .logo{margin-bottom: 25px; width: 8rem;}
		 .errorW .logo img{width: 100%;}
		 .errorW .errorTop{text-align: center; margin-bottom: 30px;}
		 .errorW .errorTop img{margin-bottom: 30px; image-rendering: crisp-edges;}
		 .errorW .errorTop p{font-size: 1.4rem; font-family: Pretendard; color: #6311b4; line-height: 1.2em; word-break: keep-all;}
		 .errorW .errorCont{border: 1px solid #e9e9e9; border-radius: 10px; overflow: hidden; margin-bottom: 50px;}
		 .errorW .errorCont h3{background-color: #f6f6f6; padding: 20px; color: #333333; font-size: 1.1rem; font-family: Pretendard, sans-serif; line-height: 1.2em;}
		 .errorW .errorCont ul{padding: 20px 1.5rem;}
		 .errorW .errorCont ul li{position: relative; padding-left: 12px; color: #717171; font-size: 1rem; font-family: Pretendard, sans-serif; line-height: 1.2em; margin-bottom: 10px; word-break: keep-all;}
		 .errorW .errorCont ul li:last-child{margin-bottom: 0;}
		 .errorW .errorCont ul li::after{content: ""; display: block; width: 5px; height: 1px; background-color: #717171; position: absolute; left: 0; top: 8px;}
		 .errorW .btnW{display: -webkit-box; display: -ms-flexbox; display: flex; padding: 0 12px;}
		 .errorW .btnW li{width: 100%; margin-right: 14px;}
		 .errorW .btnW li:last-child{margin-right: 0;}
		 .errorW .btnW li a{letter-spacing: -0.04em;}

		 .btnType2{display: block; border-radius: 4px; text-align: center; color: #fff; background-color: #4b0aeb; font-size: 1.12rem; line-height: 1.2em; box-sizing: border-box; padding: 10px 20px;}
		 .btnType3{display: block; border-radius: 4px; text-align: center; color: #fff; background-color: #313131; font-size: 1.12rem; line-height: 1.2em; box-sizing: border-box; padding: 10px 20px;}

	     @media screen and (max-width:640px){
		    .errorW .errorTop img{margin-bottom: 20px; width: 136px;}
		 }
		 @media screen and (max-width:530px){
		    .errorW{padding: 50px 16px;}
		    .errorW .btnW{padding: 0;}
		    .errorW .btnW li{margin-right: 8px;}
		 }		    















